INSERT INTO songs (song_number, title, category, songbook, song_text, tune, words, music, notes, lang, count, created_at) VALUES 
(600, 'Отпускаю все мечты мои', 0, 13, 'Куплет 1\nОтпускаю все мечты мои,\nЯ полагаю их у ног Твоих\nЕсли в жизни ошибаюсь я,\nТвоя любовь не изменяется\n\nКуплет 2\nХотел сразиться я за жизнь свою....\nОслабли руки, устал я в бою\nТы сильный Воин, Ты Царь всех побед!\nЯ побеждаю, когда я в Тебе\n\nПриспів\nИ даже если горы не двигаясь стоят\nИ если воды моря не разделяются...\nИ если на молитвы, не вижу я ответ\nДоверять, доверять буду я Тебе!\n\nКуплет 3\nЧто завтра мне принесет опять?\nТы знаешь, все известно для Тебя!\nЖиви во мне, будь дыханием моим\nДай каждый день ходить путем Твоим!\n\nКуплет 4 \nТы мой покой и сила, опора Ты моя!\nМоё Ты основание, Ты крепкая скала!\nТвои пути прекрасны, они превыше всех!\nТы держишь эту Землю и всё в Твоей руке!', '', '', '', 'ru', '', 44, NULL),
(601, 'Я в объятьях Твоих, здесь тепло, здесь покой, ', 0, 13, 'Куплет:\nЯ в объятьях Твоих, здесь тепло, здесь покой, \nНаполняет меня, неземная любовь. \nЯ в объятьях Твоих, познаю полноту \nСозерцаю я в них, всю Твою красоту \n\nПрипев:\nТы Великолепен! Ты Необыкновенный! \nЦарь над всею вселенной! Ты Чудесный, Ты Верный! \nЯ в Твоих лишь объятьях, нахожу смысл жизни,  \nВ них хочу пребывать я, в них источник всех истин. \n\nКуплет:\nЯ в Твоих объятьях я в Твоих объятьях,        \nЯ в Твоих объятьях, я в Твоих объятьях.', '', '', '', 'ru', '', 1, NULL),
(602, 'Далеко-далеко, Далеко-далеко, далеко журавли улетели', 0, 13, 'Куплет 1\nДалеко-далеко, Далеко-далеко, далеко журавли улетели\nЗа леса, за поля, где  дороги бушуют метели.\nНо лететь журавлям, но лететь журавлям нету мочи,\nИ присели они на полянку в лесной среди ночи.\nНо лететь журавлям, но лететь журавлям нету мочи,\nИ присели они на полянку в лесной среди ночи.\n\nКуплет\nА на утро друзья, поднялась ангелатая стая,\nЯ остался один среди рек и полей одинокий,\nЯ кричал им во след: "Помогите, крылатые братья,\nНету сил моих больше, нету воли и с вами подняться".\nЯ кричал им во след: "Помогите, крылатые братья,\nНету сил моих больше, нету воли и с вами подняться".\n\nКуплет\nС Новым годом друзья, с Новым счастьем я вас поздравляю\nШлю привет с далека, шлю привет с далека, снова и снова\nНо парою судьба, начинает шутить и смеяться\nВсе друзья отойдут и ни кто не поможет подняться\nНо парою судьба, начинает шутить и смеяться\nВсе друзья отойдут и ни кто не поможет подняться \n\nКуплет\nДалеко-далеко, Далеко-далеко, далеко журавли улетели\nЗа леса, за поля, где  дороги бушуют метели.\nНо лететь журавлям, но лететь журавлям нету мочи,\nИ присели они на полянку в лесной среди ночи.\nНо лететь журавлям, но лететь журавлям нету мочи,\nИ присели они на полянку в лесной среди ночи.', '', '', '', '', '', 1, NULL),
(603, 'Через кров Христа', 0, 13, 'Куплет 1\nЧерез кров Христа\nЧерез кров Христа\nСвобода нам дана 2р\nКуплет 2\nЯ дякую Тобі\nЗа те, що дав життя мені \nЯ славлю і хвалю Тебе мій Ісус\nКуплет 3\nЯ дякую Тобі\nЗа те, що дав життя мені\nЧерез кров Христа Ісуса вільними\nКуплет 4\nО, кров Ісусова спасає від гріха\nНіщо нас не спасе\nТільки кров свята Ісуса', '', '', '', '', '', 1, NULL),
(604, 'Колись  давно в Єрусалимі', 0, 13, 'Verse 1\nКолись  давно в Єрусалимі\nПодія дивна сталася\nГосподь явив Себе у силі\nНа землю Дух Святий послав\nІ учнів, що зібрались разом\nВін Духом всіх там охрестив\nВони радіючи, молились\nНарод розгублено глядів\n\n\nRefrain\nДух Святий підбадьорить тебе\nДух Святий полікує тебе\nДух Святий попровадить тебе і мене\nДух Святий буде вчити тебе\nДух Святий наповнить тебе\nДух Святий на зустріч з Христом підійме\n\nVerse 2\nУ силу Божу зодягнувшись\nУчні апостоли пішли\nЗвіщати вістку про спасіння\nЛюдей до Бога привести\nУ чудесах, знаменах дивних\nГосподь Себе там проявляв\nО, любий брате, сестро, нині\nЧи Дух Святий ти вже прийняв', '', '', '', '', '', 7, NULL),
(605, 'Чому не все так легко, життя у безпорядку', 0, 13, 'Verse 1\nЧому не все так легко, життя у безпорядку?\nЧому біль - це частина нас?\nВ житті бувають дні, коли все іде не так, -\nЦе дуже сильно ранить нас.\n\nТа Ти тут, Живий, Тобі довіряю.\nТа Ти тут, Живий, Тобі довіряю.\n\nRefrain\nІ коли болить, коли тяжко йти.\nІ переді мною два шляхи.\nДо Тебе побіжу, бо знаю хто Ти є - \nЛікар моїх ран і моя Любов.\n\nRefrain 2\nОпора моя! Опора моя!\nОпора моя! Опора моя!\nVerse 2\nНе буду хвилюватись, бо знаю, Ти тримаєш\nМене в долонях рук Своїх\nІ кожну мить в житті, всі радощі і болі\nСтаються як Ти спланував.\n\nТа Ти тут, Живий, Тобі довіряю.\nТа Ти тут, Живий, Тобі довіряю.', '', '', '', '', '', 2, NULL),
(606, 'Обрати взор на Свой народ, ', 0, 13, 'Куплет 1\nОбрати взор на Свой народ, \nИссохла земля и ждёт дождя. \nМы Тобой не забыты, это мы оставили тебя,\nНо мы хотим возвратиться в дом Отца.\n\nПриспів\nО, излей от Духа на Свои народы\nО, пролей потоки, мы жаждем тебя.\nО, излей от Духа на Свои народы,\nО, пролей потоки, мы жаждем Тебя.\n\nКуплет-Брідж\nТы Первый и Последний, Господь\nСаваоф.\nТы наш Искупитель, и нет других\nБогов.\nТы Первый и Последний, Господь Саваоф.\nТы наш Искупитель, и нет других Богов.', '', '', '', 'ru', '', 2, NULL),
(607, 'Ця земля так довго на цей день чекала,', 0, 13, 'Verse 1\nЦя земля так довго на цей день чекала,\nКоли лине з неба теплий, чистий дощ,\nКоли сонце правди порозгонить хмари,\nКоли пісню щастя заспіває хтось.\n\nПриспів\nIcycy слава, Ісусу слава!\nЛунає пісня над схилами Дніпра.\nІсусу слава, Ісусу слава!\nСпіває вільна Україна.\n\nКуплет 2\nІ цей день, нарешті, до нас увірвався,\nВін приніс нам віру в світле майбуття.\nЧрез Свого Сина, Всемогутній Батько\nНам дарує ріки вічного життя.\n\n\nКуплет 3\nЛюди України, підіймайте руки,\nПрославляйте Сина, Він - єдиний Бог.\nВін Своєю кров''ю розірвав кайдани,\nВін достойний слави - Ісус Христос.', '', '', '', '', '', 1, NULL),
(608, 'Боже, Україну збережи', 0, 13, 'Verse 1\nМинає час, минають дні, і змінюється все навколо,\nТа тільки Бог, Господь Святий, не змінюється Він ніколи.\nВ одну хвилину може Він змінити все в нашій країні,\nГосподь, благаємо Тебе, даруй спасіння Україні.\n\nПриспів\nБоже, Україну збережи, Господи, помилуй грішних,\nЗмилуйся над нами і прости, молимо Тебе, Всевишній.\nІ від ворога нас захисти, бо без Тебе ми безсилі,\nГосподи зміни все навкруги, дай спасіння Україні.\n\nКуплет 2\nІ як над цим спостерігать, якщо людей отак вбивають,\nКоли жива людська душа вже зовсім цінності не має?.. \nІ як же нам тут далі жить і нашим дітям в цій країні?\nЯкщо не вступишся, Господь, загине наша Україна!\n\nПриспів 2\nБоже, Україну збережи, Господи, помилуй грішних,\nЗмилуйся над нами і прости, молимо Тебе, Всевишній.\nІ від ворога нас захисти, бо без Тебе ми безсилі,\nГосподи зміни все навкруги, дай спасіння Україні.', '', '', '', '', '', 2, NULL),
(609, 'Ти - мій простір в тісноті', 0, 13, 'Verse 1\nТи - мій простір в тісноті,\nМоє Світло  в темряві.\nВоскресший Цар,\nНадія Ти жива\n\nСеред тисяч голосів\nВ серці чую голос Твій \nІ коли вся земля тремтить\nЗнаю я, Ти смерть переміг\n\nПриспів\nСеред хвиль я не боюся,                          \nПідіймаю руки, Бог,\nІ на хрест, коли дивлюсь я,\nТебе прославлю знов і знов\n\nПеремога й моя сила,\nКоли я був слабкий.\nВ моїй немочі Ти сильний,\nВ серці чую голос Твій\n\nКуплет 2 \nТи - мій Простір в тісноті\nТи - мій Якір для душі,\nНемов крізь море\nТи твориш новий шлях.\n\nВся хвала Тобі, мій Цар,\nПеремога в Твоїх руках\nІ коли лиш є одна мить\nЗнаю я, що зі мною Ти\n\nКуплет 3\nЗнаю, вірний, завжди, \nТи - моя сила\nВ моїй немочі Ти сильний\n\nЗнаю , вірний, завжди,\nТи - моя сила\nВ серці чую голос Твій', '', '', '', '', '', 1, NULL),
(610, 'Боже дякуєм Тобі, ми так дякуєм Тобі', 0, 13, 'Куплет 1\nБоже дякуєм Тобі, ми так дякуєм Тобі,\nТи з нами Бог поруч завжди.\nВ тіні крил Твоїх святих, заховай від бід земних,\nБудь з нами Бог, поруч завжди.\nВ смиренні з серцем на колінах Тебе молим про мир,\nВ смиренні з серцем на колінах Тебе молим про мир.\n\nПриспів\nХай сонце правди не зайде, а світить там над Україною,\nМи віримо війна мине, що ходить стороною східною.\nКожну рану Ти зціли, нехай же син прийде до матері,\nСльози гіркі їх зітри, батькам які дитину втратили.\nПомилуй, помилуй, помилуй, помилуй, помилуй.\n\nКуплет 2\nВ тіні крил Твоїх святих, заховай від бід земних,\nБудь з нами Бог, поруч завжди.\nВ смиренні з серцем на колінах Тебе молим про мир,\nПомилуй нас щоб ми не втратили свій орієнтир.\n\nКуплет / Приспів\nБлагаємо Тебе прийди, і молим в Ім’я Сина Божого,\nЩоб не один християнин, не впав від наміру ворожго.\nХай сонце правди не зайде, а світить нам над Україною,\nМи віруєм біда мине, народ за Господом послідує.\nПомилуй, помилуй, помилуй, помилуй, помилуй.\n\nКуплет / Приспів\nХай сонце правди не зайде, а світить нам над Україною,\nМи віримо війна мине, що сходить стороною східною.\nХай сонце правди не зайде, а світить нам над Україною,\nМи віруєм біда мине, народ за Господом послідує.\nПомилуй, помилуй, помилуй, помилуй, помилуй.\nХай сонце правди не зайде, а світить нам над Україною.', '', '', '', '', '', 6, NULL),
(611, 'Минає час, минають дні, і змінюється все навколо,', 0, 13, 'Куплет 1\nМинає час, минають дні, і змінюється все навколо,\nТа тільки Бог, Господь Святий, не змінюється Він ніколи.\nВ одну хвилину може Він змінити все в нашій країні,\nГосподь, благаємо Тебе, даруй спасіння Україні.\n\nПриспів\nБоже, Україну збережи, Господи, помилуй грішних, \nЗмилуйся над нами і прости, молимо Тебе, Всевишній.\nI від ворога нас захисти, бо без Тебе ми безсилі,\nГосподи зміни все навкруги, дай спасіння Україні.\n\nКуплет 2\nІ як над цим спостерігать, якщо людей отак вбивають,\nКоли жива людська душа вже зовсім цінності не має?..\nI як же нам тут далi жить i нашим дітям в цій країні?\nЯкщо не вступишся, Господь, загине наша Україна!\n\nПриспів\nБоже, Україну збережи, Господи, помилуй грішних,\nЗмилуйся над нами i прости, молимо Тебе, Всевишній.\nI від ворога нас захисти, бо без Тебе ми безсилі,\nГосподи зміни все навкруги, дай спасіння Україні.', '', '', '', '', '', 2, NULL),
(612, 'Я за Україну молюся мій Боже,', 0, 13, 'Куплет 1\nЯ за Україну молюся мій Боже,\nВірю Твоя милість людям допоможе.\nНе в пишних палацах процвітає воля,\nА в молитві з Богом України доля!\n \nПриспів\nУ молитві тихо схилимо коліна.\nЩоб всміхалась світу вільна Україна.\nІ моя молитва розірве кайдани.\nІ на Україні будуть християни.\n\nКуплет 2\nЩоб не лились сльози матінки і тата,\nЩоб була вже вільна Україна наша.\nНе вбивали кулі в молодих синів,\nБог нам тільки мирно жити повелів.\n\n   Куплет Test\nЯ за Україну молюся мій Боже,\nВірю Твоя милість людям допоможе.\nНе в пишних палацах процвітає воля,\nА в молитві з Богом України доля!', '', '', '', '', '', 10, NULL),
(613, 'Много лет говорят о чуде из чудес,', 0, 13, 'Куплет 1\nМного лет говорят о чуде из чудес,\nМного лет говорят, что Иисус воскрес!\nПусть хвалою наполнятся людей сердца,\nПрославляя любовь Воскресшего Христа.\n\nПриспів\nДа, Христос воскрес, и это чудо!\nПрославлять Его, все люди, будем –\nОн воистину воскрес!\nДа, Христос воскрес, и льются песни!\nВ этот воскресенья день чудесный –\nОн воистину воскрес!\n\nКуплет 2\nМного лет говорят о чуде из чудес,\nМного лет говорят, что Иисус воскрес.\nНе умолкнут уста людей пусть никогда,\nПусть несут эту весть чрез многие года.\n\nКуплет 3\nМного лет говорят о чуде из чудес,\nИ мы знаем, во истину Христос воскрес.\nНебеса приглашают всех людей к Нему –\nВоскресенье Христа навек сокрыло тьму.', '', '', '', 'ru', '', 8, NULL),
(614, 'За мене хрест поніс,', 0, 13, 'Куплет 1\nЗа мене хрест поніс,\nТому живу у свободі що дав Ти.\nВізьми моє життя,\nМоя душа співати буде Тобі завжди.\n\nПриспів\nГідний слави Ти Ісус\nВся хвала Тобі гідний тільки Ти!\nГідний слави Ти Ісус\nВся хвала Тобі гідний тільки Ти!\n\nКуплет 2\nТепер мій сором зник,\nМене покрив Своєю любов’ю Ти.\nЗнов сходить благодать,\nМоя душа співати буде Тобі завжди.\n\nКуплет 3\nБудь прославлений Ти на небі,\nІ вся слава на землі.\nГідний ти один хвали,\nТвоє ім’я више всіх.', '', '', '', '', '', 1, NULL),
(615, 'Ти мій Господь моя любов,', 0, 13, 'Куплет 1\nТи мій Господь моя любов,\nДух Святий в мені запалює вогонь,\nМоє життя належить Тобі,\nЯ Твоє дитя Ти є батько мій.\n\nПриспів\nВірю я, Вірю я, Вірю я\nУ Святого Духа, Сина і Отця\nВірю я, Вірю я, Вірю я\nУ Святого Духа, Сина і Отця\n\nКуплет 2\nСеред людей вибрав мене.\nБути Твоїм сином то велика честь.\nЛюбов’ю серця наповняєш Ти.\nІ даєш бажання служити.\n\nКуплет 3\nЯ на Божій стороні, Дух Святий живе в мені.\nНаставляє Він мене жити по правді.\nСил дає у боротьбі, підкріпляє у журбі.\nЗ Господом моїм живу я у свободі.', '', '', '', '', '', 1, NULL),
(616, 'З нами Саваот Господь,Творець народів всіх', 0, 13, 'Куплет 1\nЗ нами Саваот Господь, Творець народів всіх\nЗламав Він лук, зігнув Він спис, сказав війні: «спинись!»\nО, Цар Ізраїлів перемі, на нашій стороні\nІз Богом вірою ідем, спасає вірних Він\n\nПриспів:\nЗ нами Сильний Бог наш, з нами у вогні Він,\nЗ нами наче щит Він, з нами через шторм! \nПроведеш нас через бурі грізні \nКуди би не пішли ми, з нами Сильний Бог!\n\nКуплет 2\nЧерез віки Бог Якова, залишив голос свій \nЗемля тремтить, твердині всі зламав у ніг Своїх \nТи знаєш всі серця людей, даєш життя й спокій \nІз Богом перемоги йдем, бо знаєм переміг!\n\nКуплет 3\nНестримні води, чую шум вітрів, та знаю Ти-Господь,\nХто моє серце захистив!\nХоча земля тремтить, лютують нації по всій землі!\nЗнаю все Господь в руках Твоїх!', '', '', '', '', '', 3, NULL),
(617, 'Бога я шукав, і відповів мені,', 0, 13, 'Куплет 1\nБога я шукав, і відповів мені,\nІ визволив мене, від усіх страхів.\nСвітло Він для тих, в кого взір на Ньому,\nНе вкриє сором їх, не вкриє сором їх.\n\nКуплет 2\nВбогий заволав, і Господь почув,\nІ зберіг його, від ворогів.\nІ Божий Син, в оточенні святих,\nВін звільняє їх, Він звільняє їх.\n\nПриспів\nВеличайте Господа, піднесем Його Ім’я,\nВеличайте Господа, прославляй Його навіки.\n\nКуплет 3\nСкуштуй й поглянь, що Господь благий,\nБлаженний ти, в тіні Його крил.\nБійтесь Господа, усі Його святі,\nДостаток дасть тобі, достаток дасть тобі\n\nКуплет 4\nПрославляй Його, завжди й повсякчас,\nІ нехай хвала, лине знов і знов. \n\nКуплет 5\nСкуштуй й поглянь, що Господь благий,\nДостаток дасть тобі, достаток дасть тобі.', '', '', '', '', '', 6, NULL),
(619, 'Живущий под кровом Всевышнего ', 0, 13, 'Куплет 1\nЖивущий под кровом Всевышнего \nПод сенью Всемогущего покоится. \nГоворит Господу: «Прибежище моё и защита моя, \nБог, на которого уповаю я»\n\nПриспів\nПрибежище моё и защита моя, \nБог, на которого уповаю я.\nПрибежище моё и защита моя, \nБог, на которого уповаю я.\n\nКуплет 2\nЯ живу под кровом Твоим\nПод сенью Твоей покоюсь я Ты защита моя\nЯ живу под кровом Твоим\nПод сенью Твоей покоюсь я ведь Ты защита моя\n\nКуплет 3\nЯ не убоюсь я не убоюсь ужасов ночи\nЯ не убоюсь стрелы, летящей днём\nЯ не убоюсь язвы, ходящей во мраке\nЯ не убоюсь болезни ни одной\n\nКуплет 4\nПадут подле меня тысяча\nИ десять тысяч одесную меня\nНо ко мне не приблизятся\nКо мне не приблизятся', '', '', '', 'ru', '', 1, NULL),
(620, 'Неописуемый такой мой Бог', 0, 13, 'Куплет 1\nНеописуемый такой мой Бог\nВо всех путях  Своих прекрасен  мой Господь\n\nКуплет 2\nПозвал меня Ты через воды\nИ стал так близко, все изменил \nТы показал мне смысл жизни\nСвое спасенье, и новый день - пою я\n\nПриспів 1.1\nУуу, нет слов, чтоб описать\nУуу, прекрасен в Своих путях\nО Иисус, открыл Ты мои глаза\nЯ в сердце Твоем всегда мой Бог, мой Бог\n\nПриспів\nНеописуемый такой мой Бог\nВо всех путях Своих прекрасен мой Господь\nИ не понять никак, не объяснить \nВсю полноту и глубину Твоей любви\n\nКуплет 2\nСвободу дал мне, теперь дышу я\nМоя награда быть с Тобой\nВойну Ты выиграл я в Твоем Царстве\nТебя прославлю, прими хвалу - я восхищаюсь\n\nПриспів 1.1\nУуу, нет слов, чтоб описать\nУуу, прекрасен в Своих путях\nО Иисус, открыл Ты мои глаза\nЯ в сердце Твоем всегда мой Бог, мой Бог\n\nПриспів\nНеописуемый такой мой Бог                    \nВо всех путях Своих прекрасен мой Господь\nИ не понять никак, не объяснить \nВсю полноту и глубину Твоей любви\n\nНеописуемый, у-у-у \nНеописуемый, у-у-у \n\nКуплет 3\nО любовь здесь Твоя\nИзливаешь благодать\nБез Тебя жить не могу\nТы зовешь Бог,  я пойду\n\nПриспів\nНеописуемый такой мой Бог\nВо всех путях Своих прекрасен мой Господь\nИ не понять никак, не объяснить \nВсю полноту и глубину Твоей любви\n\nНеописуемый, у-у-у \nНеописуемый, у-у-у', '', '', '', 'ru', '', 1, NULL),
(621, 'Вірний і Вічний ', 0, 13, 'Куплет 1\nВірний і Вічний \nТи Господь, Ти наш Бог\nМилосердний, Цілитель\nТи Господь, Ти наш Бог\n\nПриспів\nСильний, Спаситель\nТи Господь, Ти наш Бог\nСкеля і Щит наш\nТи Господь, Ти наш Бог\n\nЩо провину може смить\nТільки Кров Христа Иисуса\n\nКуплет 2\nСтоїмо перед Тобою\nВеличаєм Твоє ім’я\nНаша Башня, наш Спаситель\nЗахистиш  нас від падіння \nПідіймаєм в небо руки \nІ несем свої молитви\nЗа людей що впала в прірву\nСтоїмо в проломі Иисус\nМи в проломі за бессильних \nЗа дітей що постраждал \nЗа зруйновані ті сім’ї\nІ за наше покоління \nТи даєш свою свободу  \nВід гріха і бессзаконня \nКоли сила знемагає \nТвоя віра надихає', '', '', '', '', '', 3, NULL),
(622, 'Возьми меня как глину и возьми меня, как стрелу', 0, 13, 'Куплет 1\nВозьми меня как глину и возьми меня, как стрелу\nСлепи из меня все что хочешь запусти меня в цель Свою\nВозьми меня как глину и возьми меня, как стрелу\nСлепи из меня все что хочешь запусти меня в цель Свою\n\nПриспів\nЯви Свою славу, яви Свою силу Иисус\nЯви Свою славу, яви Свою силу Иисус\n\nКуплет 2\nЯ верю в Чудеса я верю в Божие Слова\nЯ верю в Божию любовь через кровь, Святую Кровь\nИ всё изменится вокруг потому что Бог мой Друг, \nПотому что Он со мной Он мой Герой, Иисус Герой', '', '', '', '', '', 1, NULL),
(623, 'Великий Бог Израилев!', 0, 13, 'Приспів\nВеликий Бог Израилев!\nВеликий Бог Израилев!\nГолос Его слышен, в силе Его слов,\nВеликий Бог Израилев!\n\nКуплет 1\nИ возгремит Господь гласом славы Своей\nИ среди ночи песнь обретешь\nВзойди со свирелью на гору Его,\nИ славу Его там найдешь!\n\nКуплет 2\nСлепые глаза свет увидят в ночи,\nГлухой услышит музыки звук,\nХромые запляшут, как царь Давид,\nНемые уста запоют.', '', '', '', '', '', 1, NULL),
(624, 'Ти кожен подих мій', 0, 13, 'Куплет 1\nТи - кожен подих мій,\n Ти - кожен подих мій,\nТвоя присутність завжди в мені!  / 2р\n\nПриспів\nОсь я  перед Тобою, Господь! \nЖиву я, бо Ти зі мною, мій Бог!\n\nКуплет 2\nТи - мій щоденний Хліб,\nТи - мій щоденний Хліб,\nТи сієш слово в серце мені!   / 2 р', '', '', '', '', '', 7, NULL),
(625, 'Нехай поклоняться Тобі, всі народи, Бог мій', 0, 13, 'Куплет 1\nНехай поклоняться Тобі, всі народи, Бог мій\nБо Ти один достойний слави, Ти один святий\nНехай співають всі Тобі: Слава, слава, слава,\nСлава, слава, слава, Тобі!\nНехай молитви всі Тобі, з подякою складають\nБо Ти один достойний слави, добрий тільки Ти\nНехай співають всі Тобі: Слава, слава, слава,\nСлава, слава, слава, Тобі!\n\nПриспів\nТакий великий Бог, а так близько\nТи так близько, в серці моїм\nХоч небо над землею, так високо\nА Ти близько, в серці моїм\nТакий великий Бог\n\nКуплет 2\nНехай хвала із наших уст, буде Тобі приємна\nГосподь один достойний слави, Ти один святий\nНехай у єдності серца співають: Слава, слава, слава,\nСлава, слава, слава, Тобі!\nНехай у радості земля спасителя чекає\nГосподь один достойний слави, добрий тільки Ти\nНехай співають всі Тобі: Слава, слава, слава,\nСлава, слава, слава, Тобі!', '', '', '', '', '', 7, NULL),
(626, 'Стояв перед всім творінням', 0, 13, 'Куплет 1\nСтояв перед всім творінням\nВічність тримавши в руках\nВ людину вдихнув Ти Свій подих\nВконяюся я\n\nКуплет 2\nСтояв перед моїм падінням\nПоніс Ти за мене мій хрест\nНа плечі Свої взяв весь гріх мій\nВконяюся я\n\nКуплет 3\nЩо зроблю я?\nЩо я скажу?\nЛиш серце своє Мій Бог Тобі віддаю\n\nКуплет 4\nСтою піднявши Свій поглад в небо\nТому, Хто один віддав усе \nСтою, до Тебе схиляю серце\nВсе в мені Твоє\n\nКуплет 5\nЯ берегтиму спасіння\nВеде Дух Святий мене\nУ руки Свої взяв життя Ти\nВконяюся я\n\nКуплет 6\nЩо зроблю я?\nЩо я скажу?\nЛиш серце своє Мій Бог Тобі віддаю\n\nКуплет 7\nСтою піднявши Свій поглад в небо\nТому, Хто один віддав усе \nСтою, до Тебе схиляю серце\nВсе в мені Твоє', '', '', '', '', '', 1, NULL),
(627, 'Славим Того хто життя дарував', 0, 13, 'Куплет 1\nСлавим Того хто життя дарував\nЛюдство створив і природу нам дав\nЗорі створив і на небі розклав\nСонце нам дав, місяць дав, воду дав\n\nПриспів\nБудь прославлений наш Бог\nЗ нами Бог так з нами Бог\nІ життя вже не сумне з нами Бог\nІ з нами все\n\nКуплет 2\nСкоро грядеш Ти у славі своїй\nЦеркву візьмеш і одягнеш вінці\nКнига відкрита лежить перед Ним\nНаші ім''я там записані в ній\n\nКуплет 3\nТвоє ім''я: Цар царів, Бог богів\nВище всього і сильніший усіх\nБачиш моє Ти нутро і життя\nБоже, Тобі вся хвала, вся хвала', '', '', '', '', '', 12, NULL),
(628, 'Славимо, ми славимо/Давай будемо ми славити Бога,', 0, 13, 'Приспів\nСлавимо, ми славимо,\nСлавимо Святого Отця.\nЛюбимо, ми любимо\nСлавити Його без кінця.\n\nКуплет 1\nДавай будемо ми славити Бога,\nБо Він гідний хвали завжди, завжди.\nМи здіймаєм руки свої до небес і славимо Отця,\nБо нас поєднала в єдину сім’ю милість і любов Творця.\n\nКуплет 2\nДавай будемо ми співати Христові\nЩоби наша хвала сягнула небес.\nБо так полюбив нас Отець, що віддав Синове життя,\nЩоб ми жили вічно й хвалили Його, нашого Творця', '', '', '', '', '', 1, NULL),
(629, 'Aquí estás Te vemos mover/Ти є тут зцілюєш серця', 0, 13, 'Куплет 1\nAquí estás Te vemos mover\nTe adoraré, Te adoraré\nAquí estás, Obrando en mí\nTe adoraré, Te adoraré\n\nПриспів 1\nMilagroso, abres camino\nCumples promesas\nLuz en tinieblas\nMi Dios, así eres Tú\n\nКуплет 2\nТи є тут зцілюєш серця\nТвоє Ім‘я прославлю я.\nТи є тут змінюєш життя\nТвоє Ім‘я прославлю я.\n\nПриспів 2\nПровадиш, чуда вчиняєш\nТи Бог вірний, світло в темряві.\nМій Бог, знаю, Хто Ти є!\nЗнаю, Хто Ти є! (4р.)\n\nКуплет 3\nІ коли навіть не відчуваю\nВсе одно довіряю і знаю:\nНіколи нас Ти не залишаєш!\nНіколи нас Ти не залишаєш!', '', '', '', 'es', '', 3, NULL),
(630, 'Мене Ти кличеш над водою', 0, 13, 'Куплет 1\nМене Ти кличеш над водою\nДе не встоїть моя нога\nТебе в пригодах відшукаю\nОсяє віра океан\n\nПриспів\nТвоє ім''я прикличу я\nСховаю очі в небесах\nДуша моя спочине у Твоїх руках\nТи мій Господь в Тобі є я\n\nКуплет 2\nВ глибинах вод перебуває\nТвоя безмежна благодать\nДе страх і темрява стискають\nТвоя рука покаже шлях\n\nКуплет 3\nДух, веди мене невпинно за Собою\nЩоб ходив я над водою куди б Ти не покликав\nПроведи мене в глибинах неосяжних\nЩоб міцніла віра завжди у Твоїх очах, Спаситель', '', '', '', '', '', 1, NULL),
(631, 'Quién rompe el poder del pecado/Хто відродив нас і дав надію', 0, 13, 'Куплет 1\nQuién rompe el poder del pecado,\nSu Amor es fuerte y poderoso\nEl Rey de gloria, el Rey de Majestad\nConmueve el mundo con su estruendo,\ny nos asombra con maravillas\nEl Rey de gloria,\nel Rey de Majestad\n\nПриспів 1\nGracia Sublime es, Perfecto es tu amor\nTomaste mi lugar, Cargaste Tu mi cruz\nTu vida diste ahí, Y ahora libre soy\nJesús te Adoro por lo que hiciste en mi\n\nКуплет 2\nХто відродив нас і дав надію\nХто всиновив нас і завжди вірний\nГосподь могутній, Ти над царями - Цар.\nХто править в правді, хто\nсправедливий,\nХто в славі сяє, Величний, Сильний,\nГосподь могутній, Ти над царями - Цар.\n\nПриспів 2\nЧудова благодать… Мене Ти полюбив,\nПоніс усі гріхи, За мене на хресті,\nВіддав Своє життя, Щоб я свободу мав,\nТебе прославлю за все, що Ти нам дав\n\nКуплет 3\nГідний Агнець честі й хвали\nГідний слави Цар, що смерть переміг\n(4р)', '', '', '', 'es', '', 0, NULL),
(632, 'Al mundo Paz nació Jesús', 0, 13, 'Verse 1\nAl mundo Paz, nació Jesús,\nnació ya nuestro Rey.\nNació el Salvador,\nÉl es nuestro Señor,\nJesucristo nació,\nJesucristo nació,\ny paz al mundo Él nos dio.\n\nVerse 2\nAl mundo Paz, el salvador\nen Tierra reinará.\nA cada pecador\nJesús le da perdón,\nJesús le da perdón\nJesús, Jesús le da perdón.\n\nVerse 3\nAl mundo Paz, gobernará\ncon Gracia y poder:\nnaciones probará\nsu amor y su poder\nsu amor y su poder\nsu amor, su amor y su poder.', '', '', '', 'es', '', 0, NULL),
(633, 'Ти з нами, Бог!', 0, 13, 'Куплет 1\nЗ глибини душі моєї\nЛлється пісня в небеса.\nТобі, Господи, співаю!\nЗнаю - це краса!\nВік проходить, час минає.\nВ серці - Благодаті Храм.\nПрояв Божої любові -\nЦе є дар по вірі нам!\n \nПриспів\nТи з нами, Бог!\nТи з нами, Бог!\nСлавим Ім''я Христа\nВ сяйві неба зірок.\nТи з нами, Бог!\nТи з нами, Бог!\nТільки в серці наша віра\nПроросте, як колосок.\nТи з нами, Бог!\n\nКуплет 2\nПісню Небо зустрічає,\nЧути різні голоси.\nТож нехай нам підспівають\nСонце і ліси.\nПісня ця - в ім''я спасіння,\nПро кохання на Землі,\nПро рясне Благословіння,\nЩо дано тобі й мені.\n\nКуплет 3\nВ серці Бог, Він є у пісні.\nЄ у росах і в сльозі,\nЄ у щасті й коли горе,\nВ сонці і в красі.\nТож, співайте всі довкола:\nОкеани і моря.\nІм''я Господа і Віру\nВ пісні прославляю я!', '', '', '', '', '', 1, NULL),
(634, 'Лише Один хто сильний щоб спасти', 0, 13, 'Куплет 1\nЛише Один хто сильний щоб спасти\nЛише Один зміг смерть перемогти\nЛише Один хвали достойний Він\nВ руках Його від пекла є ключі\nІм‘я Його зцілити може всіх\nІ Кров Його геть з нас змиває гріх  \n\nПриспів\nЙого Ім‘я Ісус\nЙого Ім‘я Ісус\nЙого Ім‘я Великий Бог\nПорадник наш, Могутній Бог  \n\nКуплет 2\nНароди всі схиляться у хвалі\nБо прийде Він, нехай земля тремтить\nСудити всіх і мертвих і живих  \nОсь Син людьский гряде на хмарах в світ\nНебесний клич - й коліна схилять в мить\nПризнають всі Ім‘я що вище всіх\n                             \nКуплет 3\nНам Порадник Він (Нам Порадник Він)\nВін є Бог богів (Він є Бог богів)\nВін є Цар царів (Він є Цар царів)\nВсемогутній Він (Всемогутній Він)\nДивовижний Він (Дивовижний Він)\nСяє нам усім  (Сяє нам усім)\nВін є Цар царів\n\nКуплет 4\nСхиляємось (Схиляємось)\nІ віддаєм життя (І віддаєм життя)\nПісня лине  (Пісня лине)\nБог до Тебе (Бог до Тебе)', '', '', '', '', '', 0, NULL);